import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync, existsSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import test from 'node:test';
import { readRigDoc } from '../scripts/rig_doc.mjs';

/**
 * Guards the rigs that actually ship.
 *
 * `public/rigs` is generated by `scripts/publish_rigs.mjs` from `experiments/rig-lab`, and the game
 * loads one document per art at runtime. A broken document does not fail the build — it fails in
 * the browser, silently, as a heroine who does not move. These tests are the stand-in for a
 * browser: they check the invariants the runtime relies on and the ones that are easy to lose when
 * a script is re-run.
 */

const RIGS = join(import.meta.dirname, '..', 'public', 'rigs');
const index = JSON.parse(readFileSync(join(RIGS, 'index.json'), 'utf8')) as Record<
  string,
  { file: string; plate: string; animations: string[]; hasMouth: boolean; bones: number }
>;

test('index lists the arts that have a face kit', () => {
  // The count comes from the face kit, not from a number in this file: every art with an
  // `eyes_closed` patch has to be publishable, and nothing else may claim to be. A literal here
  // means a newly rigged art fails the suite instead of shipping — which is exactly backwards.
  const manifest = JSON.parse(
    readFileSync(join(import.meta.dirname, '..', 'public', 'art', 'face_kit', 'manifest.json'), 'utf8'),
  ) as Record<string, { patches?: Record<string, unknown> }>;
  const expected = Object.entries(manifest)
    .filter(([, entry]) => 'eyes_closed' in (entry.patches ?? {}))
    .map(([key]) => key.replace('heroine_', ''))
    .sort();
  const arts = Object.keys(index).sort();
  assert.deepEqual(arts, expected, `published rigs differ from the arts with a face kit`);
  for (const [art, entry] of Object.entries(index)) {
    assert.ok(existsSync(join(RIGS, `${art}.obonb`)), `${art}: ${entry.file} is missing`);
    assert.ok(entry.animations.includes('idle'), `${art}: no idle animation`);
    assert.ok(entry.animations.includes('shake'), `${art}: no shake animation`);
    assert.ok(entry.animations.includes('blink'), `${art}: no blink animation`);
  }
});

test('every plate the scene can show is either rigged or a recorded skip', () => {
  // The rig is optional per plate, but the CHOICE has to be written down. A plate the scene can
  // show, with no rig and no entry in the manifest, is the "she is a picture again" hole this whole
  // pipeline exists to close — and it is invisible from any single file.
  const manifest = JSON.parse(
    readFileSync(join(import.meta.dirname, '..', 'public', 'art', 'face_kit', 'manifest.json'), 'utf8'),
  ) as Record<string, { skip?: boolean }>;
  const src = join(import.meta.dirname, '..', 'src');
  const plates = new Set<string>();
  const walk = (dir: string) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const path = join(dir, entry.name);
      if (entry.isDirectory()) walk(path);
      else if (entry.name.endsWith('.ts')) {
        for (const m of readFileSync(path, 'utf8').matchAll(/\/art\/heroine_([a-z0-9_]+)\.webp/g)) {
          plates.add(m[1]!);
        }
      }
    }
  };
  walk(src);
  assert.ok(plates.size > 20, `plate scan found only ${plates.size} arts — the regex or the layout moved`);
  const missing = [...plates].filter((art) => !index[art] && !manifest[`heroine_${art}`]?.skip);
  assert.deepEqual(missing, [], `these plates have no rig and no recorded reason: ${missing.join(', ')}`);
});

const rig = (art: string) => index[art]!;

test('two arts that ship the same plate ship the same face kit', () => {
  // `heroine_t4_flash.webp` and `heroine_t4_s3.webp` are byte-identical files, and the manifest
  // still carried two different eye box sets for them: t4_s3's sat 10-15 px higher, so its drift
  // number measured eyebrows rather than skin. On identical pixels both cannot be right, and there
  // is no way to notice that by looking at one art at a time — so the suite compares the files.
  const manifest = JSON.parse(
    readFileSync(join(import.meta.dirname, '..', 'public', 'art', 'face_kit', 'manifest.json'), 'utf8'),
  ) as Record<string, { eyes?: number[][]; mouth?: number[]; face?: number[] }>;
  const art = join(import.meta.dirname, '..', 'public', 'art');
  const byBytes = new Map<string, string[]>();
  for (const key of Object.keys(manifest)) {
    const name = key.replace('heroine_', '');
    const file = join(art, `heroine_${name}.webp`);
    if (!existsSync(file)) continue;
    const hash = createHash('sha1').update(readFileSync(file)).digest('hex');
    byBytes.set(hash, [...(byBytes.get(hash) ?? []), name]);
  }
  for (const names of byBytes.values()) {
    if (names.length < 2) continue;
    const entries = names.map((name) => manifest[`heroine_${name}`]!);
    const first = entries[0]!;
    const rest = entries.slice(1);
    for (const other of rest) {
      assert.deepEqual(other.eyes, first.eyes, `${names.join(' / ')}: eye boxes differ on one plate`);
      assert.deepEqual(other.mouth, first.mouth, `${names.join(' / ')}: mouth box differs on one plate`);
    }
  }
});

test('art with food at the mouth never animates the mouth', () => {
  for (const art of ['t6_s1', 't6_s2', 't6_s3']) {
    assert.equal(rig(art).hasMouth, false, `${art} must not ship a mouth slot`);
    assert.ok(!rig(art).animations.includes('idle_talk'), `${art} must not ship idle_talk`);
  }
  // ...and arts without a prop do have it, or the talk state would be dead weight.
  for (const art of ['t1_s0', 't5_start_hq2']) {
    assert.equal(rig(art).hasMouth, true, `${art} should ship a mouth slot`);
    assert.ok(rig(art).animations.includes('idle_talk'), `${art} should ship idle_talk`);
  }
});

for (const [art, entry] of Object.entries(index)) {
  test(`${art}: document is consistent`, () => {
    const doc = readRigDoc(join(RIGS, `${art}.obonb`));

    assert.equal(doc.width, 1024, 'canvas width');
    assert.equal(doc.height, 1526, 'canvas height');
    assert.equal(doc.originX, 0, 'originX');
    assert.equal(doc.originY, 0, 'originY');
    assert.equal(doc.images[0].src, entry.plate, 'the body image must be the plate of this art');

    // Docs are authored y-DOWN, in plate pixels: everything must sit inside the canvas. This is
    // what `LiveHeroine` compensates for by neutralising the runtime's y-up flip, so a document
    // that drifts outside the canvas means the compensation is now hiding a real error.
    const mesh = doc.skeleton.skins[0].attachments.slot_body.miya_body;
    const verts: number[] = mesh.vertices;
    for (let i = 0; i < verts.length; i += 2) {
      const v = verts[i]!;
      assert.ok(v >= 0 && v <= doc.width, `${art}: vertex x ${v} outside canvas`);
    }
    for (let i = 1; i < verts.length; i += 2) {
      const v = verts[i]!;
      assert.ok(v >= 0 && v <= doc.height, `${art}: vertex y ${v} outside canvas`);
    }

    // Mesh bookkeeping the renderer depends on.
    assert.equal(
      verts.length / 2,
      (mesh.grid.cols + 1) * (mesh.grid.rows + 1),
      `${art}: grid metadata does not match the vertex count`,
    );
    assert.equal(mesh.uvs.length, verts.length, `${art}: one uv per vertex`);
    assert.equal(mesh.weights.length, verts.length / 2, `${art}: one weight set per vertex`);
    for (const set of mesh.weights) {
      const sum = set.reduce((acc: number, w: { weight: number }) => acc + w.weight, 0);
      assert.ok(Math.abs(sum - 1) < 1e-3, `${art}: weights sum to ${sum}, not 1`);
      for (const w of set) {
        assert.ok(
          doc.skeleton.bones.some((b: { id: string }) => b.id === w.bone),
          `${art}: weight points at unknown bone ${w.bone}`,
        );
      }
    }

    // Every animation must open on the setup pose: OpenBone timelines are absolute, so a key of
    // "0" on a bone that sits at -260 teleports it to the origin.
    const bones = new Map<string, Record<string, number>>(
      doc.skeleton.bones.map((b: { id: string }) => [b.id, b]),
    );
    for (const anim of doc.animations) {
      for (const timeline of anim.timelines) {
        if (timeline.target !== 'bone') continue;
        const bone = bones.get(timeline.id);
        assert.ok(bone, `${art}/${anim.name}: timeline targets unknown bone ${timeline.id}`);
        const first = timeline.keys[0].value as number;
        const setup = bone[timeline.property] ?? Number.NaN;
        assert.ok(
          Math.abs(first - setup) < 1e-6,
          `${art}/${anim.name}: ${timeline.id}.${timeline.property} opens at ${first}, setup is ${setup}`,
        );
      }
    }

    // The runtime reads `scripts.length` on the document and iterates `scripts` on every state
    // machine start. A document without those fields does not fail loudly — it throws inside the
    // animation loop, which is how a missing empty array became a black screen on the deployed site.
    assert.ok(Array.isArray(doc.scripts), `${art}: document.scripts must be an array`);
    for (const machine of doc.stateMachines ?? []) {
      assert.ok(Array.isArray(machine.scripts), `${art}: state machine ${machine.id} needs scripts: []`);
      for (const layer of machine.layers ?? []) {
        for (const state of layer.states ?? []) {
          const animationId = state.animation;
          assert.ok(
            doc.animations.some((a: { id: string }) => a.id === animationId),
            `${art}/${machine.id}: state ${state.id} points at unknown animation ${animationId}`,
          );
          assert.equal(
            layer.states.filter((s2: { id: string }) => s2.id === state.id).length,
            1,
            `${art}/${machine.id}: duplicate state id ${state.id}`,
          );
        }
      }
    }

    // Physics constraints must point at real bones, or the runtime silently skips them.
    for (const c of doc.skeleton.physics ?? []) {
      assert.ok(bones.has(c.bone), `${art}: physics points at unknown bone ${c.bone}`);
    }
    assert.ok((doc.skeleton.physics ?? []).length >= 2, `${art}: expected hair and bust physics`);
  });
}
